Trần Thanh Mẫn","isVerbatim":true}},"parts":[{"id":"doc_1788363998678_part_0","title":"Phần chung","start":"Điều 1","end":"Điều 107","count":107}],"appendices":{},"appendixAiData":""},"doc_1788364015441":{"name":"ism-mnt-en.docx","importMode":"iosa","articles":{"MNT 1.1.1":{"id":"MNT 1.1.1","code":"MNT 1.1.1","title":"MNT 1.1.1 The Operator shall have a management system for maintenance operations that ensures:","chapter":"MNT Section 1.1","partTitle":"MNT (Part 1)","partId":"doc_1788364015441_part_1","plainText":"MNT 1.1.1
